// Original synthetic test material only. No sourcebook content is checked into Git.
function pdf(pages){const objects=['<< /Type /Catalog /Pages 2 0 R >>',null,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];const kids=[];
 for(const lines of pages){const page=objects.length+1,content=page+1;kids.push(page+' 0 R');objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 3 0 R >> >> /Contents ${content} 0 R >>`);const text='BT /F1 11 Tf 40 750 Td 14 TL '+lines.map(t=>'('+t.replace(/([\\()])/g,'\\$1')+') Tj T*').join(' ')+' ET';objects.push(`<< /Length ${Buffer.byteLength(text)} >>\nstream\n${text}\nendstream`)}
 objects[1]=`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${pages.length} >>`;let value='%PDF-1.7\n',offsets=[0];objects.forEach((obj,i)=>{offsets.push(Buffer.byteLength(value));value+=`${i+1} 0 obj\n${obj}\nendobj\n`});const start=Buffer.byteLength(value);value+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`+offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF\n`;return Buffer.from(value)}
module.exports={pdf};
